def solve(grid, start, goal):
    def neighbors(row, col):
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = row + dr, col + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and grid[nr][nc] == '.':
                yield nr, nc

    def bfs(start, visited, parent, direction):
        queue = deque([start])
        visited[start] = True
        while queue:
            row, col = queue.popleft()
            for nr, nc in neighbors(row, col):
                if not visited.get((nr, nc)):
                    visited[(nr, nc)] = True
                    parent[(nr, nc)] = (row, col)
                    queue.append((nr, nc))
                    if direction and (nr, nc) in reverse_visited:
                        return (nr, nc)
                    if not direction and (nr, nc) in forward_visited:
                        return (nr, nc)
        return None

