    if not (0 <= goal[0] < rows and 0 <= goal[1] < cols and grid[goal[0]][goal[1]] == '.'):
        return []
    if start == goal:
        return [start]

    forward_visited, reverse_visited = {start: True}, {goal: True}
    forward_parent, reverse_parent = {}, {}
    meet = None

    while True:
        mid = bfs(start, forward_visited, forward_parent, True)
        if mid:
            meet = mid
            break
        mid = bfs(goal, reverse_visited, reverse_parent, False)
        if mid:
            meet = mid
            break
