    def bfs(starts):
        queue = deque(starts)
        visited = {s: None for s in starts}
        while queue:
            current = queue.popleft()
            for neighbor in get_neighbors(*current):
                if neighbor not in visited:
                    visited[neighbor] = current
                    queue.append(neighbor)
        return visited

