def solve(grid, start, goal):
    if start == goal:
        return [start]

    rows, cols = len(grid), len(grid[0])
    if (not (0 <= start[0] < rows and 0 <= start[1] < cols and 0 <= goal[0] < rows and 0 <= goal[1] < cols)
        or grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#'):
        return []

    def bfs(frontier, is_forward):
        moves = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        if not is_forward:
            moves = [(0, -1), (-1, 0), (0, 1), (1, 0)]
        parent = {}
        visited = set()

        while frontier:
            cell = frontier.popleft()
            if cell in visited:
                continue
            visited.add(cell)

            r, c = cell
            for dr, dc in moves:
                nr, nc = r + dr, c + dc
                if (0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.'):
                    neighbor = (nr, nc)
                    if neighbor not in parent:
                        parent[neighbor] = cell
                        if neighbor not in (set(frontier) | visited):
                            frontier.append(neighbor)

        return parent, visited

    forward = deque([start])
    backward = deque([goal])
    while forward and backward:
        parent_f, visited_f = bfs(forward, True)
        if any(cell in backward for cell in visited_f):
            return build_path(start, goal, parent_f, visited_f)
        parent_b, visited_b = bfs(backward, False)
        if any(cell in visited_f for cell in visited_b):
            path_f = [start]
            cell = next(cell for cell in visited_f if cell in visited_b)
            while cell != start:
                path_f.insert(1, parent_f[cell])
                cell = path_f[1]
            path_b = [cell]
            cell = next(cell for cell in visited_b if cell in path_b)
            while cell != goal:
                path_b.append(parent_b[cell])
                cell = path_b[-1]
            return path_b

        if not visited_f or not visited_b:
            return []

    return []

def build_path(start, goal, parent_f, visited_f):
    path = [start]
    cell = next(cell for cell in visited_f if cell == goal)
    if cell == goal:
        return [start, goal]
    while cell != start:
        path.insert(1, parent_f[cell])
        cell = path[1]
    return path
