from collections import deque
from typing import List, Tuple

def solve(grid: List[str], start: Tuple[int, int], goal: Tuple[int, int]) -> List[Tuple[int, int]]:
    if not grid or not grid[0]:
        return []
    rows = len(grid)
    cols = len(grid[0])

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    # Check if start or goal is a wall or out of bounds
    if not is_valid(*start) or not is_valid(*goal):
        return []

    if start == goal:
        return [start]

    # BFS from start to goal
    def bfs(from_point, to_point):
        visited = {from_point}
        queue = deque([(from_point, [from_point])])
        while queue:
            (r, c), path = queue.popleft()
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = r + dr, c + dc
                if (nr, nc) == to_point:
                    return path + [(nr, nc)]
                if is_valid(nr, nc) and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    queue.append(((nr, nc), path + [(nr, nc)]))
        return []

    return bfs(start, goal)
