from collections import deque, defaultdict

def solve(grid, start, goal):
    if (
        not grid or
        not 0 <= start[0] < len(grid) or
        not 0 <= start[1] < len(grid[0]) or
        not 0 <= goal[0] < len(grid) or
        not 0 <= goal[1] < len(grid[0]) or
        grid[start[0]][start[1]] == '#' or
        grid[goal[0]][goal[1]] == '#'
    ):
        return []

    if start == goal:
        return [start]

    rows, cols = len(grid), len(grid[0])
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    def bfs(start_queue, start_visited, end_visited):
        while start_queue:
            level = defaultdict(list)
            for _ in range(len(start_queue)):
                cell = start_queue.popleft()
                for dr, dc in directions:
                    r, c = cell[0] + dr, cell[1] + dc
                    if 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.' and (r, c) not in start_visited:
                        start_visited.add((r, c))
                        level[(r, c)].append(cell)
                        start_queue.append((r, c))
            for cell in level:
                if cell in end_visited:
                    return reconstruct_path(level, end_visited, cell)
        return None

    def reconstruct_path(level, end_visited, meet_point):
        path = [meet_point]
        prev = level[meet_point][-1]
        while prev in end_visited:
            path.append(prev)
            if prev == path[-2]:  # To avoid infinite loop in case of start == goal
                break
            for p in level:
                if prev in level[p] and p != meet_point:
                    prev = p
                    break
            else:
                for k, v in level.items():
                    if prev in v:
                        path.append(k)
                        prev = k
        path.reverse()
        return path

    q1, q2 = deque([start]), deque([goal])
    v1, v2 = {start}, {goal}
    while q1 and q2:
        found = bfs(q1, v1, v2)
        if found:
            return found
        found = bfs(q2, v2, v1)
        if found:
            return [goal] + found[::-1]
        if not found:
            break
    return []
