                    if 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.' and (r, c) not in start_visited:
                        start_visited.add((r, c))
                        level[(r, c)].append(cell)
                        start_queue.append((r, c))
            for cell in level:
                if cell in end_visited:
                    return reconstruct_path(level, end_visited, cell)
        return None

    def reconstruct_path(level, end_visited, meet_point):
        path = [meet_point]
        prev = level[meet_point][-1]
        while prev in end_visited:
            path.append(prev)
            if prev == path[-2]:  # To avoid infinite loop in case of start == goal
                break
            for p in level:
                if prev in level[p] and p != meet_point:
                    prev = p
                    break
            else:
                for k, v in level.items():
                    if prev in v:
                        path.append(k)
                        prev = k
        path.reverse()
        return path

