    v1, v2 = {start}, {goal}
    while q1 and q2:
        found = bfs(q1, v1, v2)
        if found:
            return found
        found = bfs(q2, v2, v1)
        if found:
            return [goal] + found[::-1]
        if not found:
            break
    return []

