        return not (0 <= row < rows and 0 <= col < cols and grid[row][col] == '.')

    def dfs(limit, current, path, visited):
        if is_wall(*current):
            return False
        if current == goal:
            path.append(current)
            return True
        if limit <= 0:
            return False
        row, col = current
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = row + dr, col + dc
            if (nr, nc) not in visited and not is_wall(nr, nc):
                path.append(current)
                visited.add((nr, nc))
                if dfs(limit - 1, (nr, nc), path, visited):
