                        return (nx, ny)
                    if (nx, ny) == (px, py):
                        break
                    nx += dx
                    ny += dy
            diagonal_moves = [(-1, -1), (-1, 1), (1, -1), (1, 1)]
            for dx, dy in diagonal_moves:
                nx, ny = x + dx, y + dy
                if is_valid(nx, ny):
                    if (grid[x + dx // 2][y] == '.' or grid[x][y + dy // 2] == '.'):
                        return (nx, ny)
            return None

