                (is_wall(r, c + dc) or
                 jump(r, c + dc, 0, dc))):
                return r, c

        nr, nc = r + dr, c + dc
        res = jump(nr, nc, dr, dc)
        if res:
            return res
        return None

    def successors(r, c):
        succ = []
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            j = jump(r, c, dr, dc)
            if j:
                succ.append(j)
        return succ

    def heuristic(p1, p2):
        pr, pc = p1
        qr, qc = p2
        return abs(pr - qr) + abs(pc - qc)

    def dir_to(r1, c1, r2, c2):
        dr = 0 if r1 == r2 else (r2 - r1) // abs(r2 - r1)
        dc = 0 if c1 == c2 else (c2 - c1) // abs(c2 - c1)
        return dr, dc

    def jump_point_search():
        open_set = [(heuristic(start, goal), 0, start, None, None)]
        visited = set()
        parent = {}
        g = {start: 0}

        while open_set:
            _, cost, current, dirr, cdir = open_set.pop(0)
            if current in visited:
                continue
            if current == goal:
                # Reconstruct path
                path = []
                while current in parent:
                    path.append(current)
                    current = parent[current]
                path.append(start)
