    came_from = {}
    g_score = {start: 0}
    f_score = {start: manhattan(start, goal)}

    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    while open_set:
        _, r, c = heapq.heappop(open_set)
        current = (r, c)
