        r, c = pos
        dr, dc = dir
        nr, nc = r + dr, c + dc
        if not (0 <= nr < len(grid) and 0 <= nc < len(grid[0])) or grid[nr][nc] == '#':
            return None
        if (nr, nc) == goal:
            return (nr, nc)
        if (nr - r) % dr != 0 or (nc - c) % dc != 0:
            return (nr, nc)
        if is_wall((r + dr, c)) or is_wall((r, c + dc)):
            return (r + dr, c + dc)
        return jump((nr, nc), dir)

