def solve(grid, start, goal):
    def neighbors(pos):
        row, col = pos
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            r, c = row + dr, col + dc
            if 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.':
                yield (r, c)

    def is_wall(pos):
        r, c = pos
        return not (0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.')

    def jps_search(grid, start, goal):
        if start == goal or grid[start[0]][start[0]] == '#' or grid[goal[0]][goal[1]] == '#':
            return [start] if start == goal else []

        open_set = set([start])
        came_from = {}
        jump_points = set()
        g_score = {start: 0}
        f_score = {start: 0}
        # BFS style search
        queue = [start]
        while queue:
            current = queue.pop(0)
            if current == goal:
                return reconstruct_path(came_from, current)
            open_set.discard(current)
            jump_points.clear()
            for next_pos in neighbors(current):
                if next_pos not in came_from or g_score[next_pos] > g_score[current] + 1:
                    came_from[next_pos] = current
                    g_score[next_pos] = g_score[current] + 1
                    f_score[next_pos] = g_score[next_pos]
                    if next_pos not in open_set:
                        open_set.add(next_pos)
                        queue.append(next_pos)
            for next_pos in list(open_set):
                rx, cx = next_pos
                for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    if dx == 0 and dy == 0:
                        continue
                    next_pos = (rx, cx)
                    step = (dx, dy)
                    if jump((rx, cx), (rx + dx, cx + dy), grid, step, is_wall):
                        jump_points.add((rx, cx))
        return []

    def jump(pos, next_pos, grid, dir, is_wall):
        r, c = pos
        dr, dc = dir
        nr, nc = next_pos
        if is_wall((nr, nc)):
            return False
        forced_neighbors = []
        if dr == -1:
            if dc == 0:
                if not is_wall((nr, c - 1)) and is_wall((nr + 1, c - 1)):
                    forced_neighbors.append((nr, c - 1))
                if not is_wall((nr, c + 1)) and is_wall((nr + 1, c + 1)):
                    forced_neighbors.append((nr, c + 1))
            elif dc == -1:
                if is_wall((r, c - 1)) or (is_wall((r - 1, c - 1)) and not is_wall((r - 1, c))):
                    forced_neighbors.append((r, c - 1))
            else:  # dc == 1
                if is_wall((r, c + 1)) or (is_wall((r - 1, c + 1)) and not is_wall((r - 1, c))):
                    forced_neighbors.append((r, c + 1))
        elif dr == 1:
            if dc == 0:
                if not is_wall((nr, c - 1)) and is_wall((nr - 1, c - 1)):
                    forced_neighbors.append((nr, c - 1))
                if not is_wall((nr, c + 1)) and is_wall((nr - 1, c + 1)):
                    forced_neighbors.append((nr, c + 1))
            elif dc == -1:
                if is_wall((r, c - 1)) or (is_wall((r + 1, c - 1)) and not is_wall((r + 1, c))):
                    forced_neighbors.append((r, c - 1))
            else:  # dc == 1
                if is_wall((r, c + 1)) or (is_wall((r + 1, c + 1)) and not is_wall((r + 1, c))):
                    forced_neighbors.append((r, c + 1))
        elif dc == -1:
            if not is_wall((r - 1, c)) and is_wall((r - 1, c - 1)):
                forced_neighbors.append((r - 1, c))
            if not is_wall((r + 1, c)) and is_wall((r + 1, c - 1)):
                forced_neighbors.append((r + 1, c))
        else:  # dc == 1
            if not is_wall((r - 1, c)) and is_wall((r - 1, c + 1)):
                forced_neighbors.append((r - 1, c))
            if not is_wall((r + 1, c)) and is_wall((r + 1, c + 1)):
                forced_neighbors.append((r + 1, c))

        for fn in forced_neighbors:
            if not is_wall(fn):
                return True  # It is a jump point

        if (nr, nc) == goal:
            return True
        elif jump((nr, nc), (nr + dr, nc + dc), grid, dir, is_wall):
            return True
        return False

    def reconstruct_path(came_from, current):
        total_path = [current]
        while current in came_from:
            current = came_from[current]
            total_path.append(current)
            if current == start:
                break
        total_path.reverse()
        return total_path

    return jps_search(grid, start, goal)
