                if not is_wall((nr, c - 1)) and is_wall((nr + 1, c - 1)):
                    forced_neighbors.append((nr, c - 1))
                if not is_wall((nr, c + 1)) and is_wall((nr + 1, c + 1)):
                    forced_neighbors.append((nr, c + 1))
            elif dc == -1:
                if is_wall((r, c - 1)) or (is_wall((r - 1, c - 1)) and not is_wall((r - 1, c))):
                    forced_neighbors.append((r, c - 1))
            else:  # dc == 1
                if is_wall((r, c + 1)) or (is_wall((r - 1, c + 1)) and not is_wall((r - 1, c))):
                    forced_neighbors.append((r, c + 1))
        elif dr == 1:
            if dc == 0:
                if not is_wall((nr, c - 1)) and is_wall((nr - 1, c - 1)):
                    forced_neighbors.append((nr, c - 1))
                if not is_wall((nr, c + 1)) and is_wall((nr - 1, c + 1)):
                    forced_neighbors.append((nr, c + 1))
            elif dc == -1:
                if is_wall((r, c - 1)) or (is_wall((r + 1, c - 1)) and not is_wall((r + 1, c))):
                    forced_neighbors.append((r, c - 1))
            else:  # dc == 1
                if is_wall((r, c + 1)) or (is_wall((r + 1, c + 1)) and not is_wall((r + 1, c))):
                    forced_neighbors.append((r, c + 1))
        elif dc == -1:
            if not is_wall((r - 1, c)) and is_wall((r - 1, c - 1)):
                forced_neighbors.append((r - 1, c))
            if not is_wall((r + 1, c)) and is_wall((r + 1, c - 1)):
                forced_neighbors.append((r + 1, c))
        else:  # dc == 1
            if not is_wall((r - 1, c)) and is_wall((r - 1, c + 1)):
                forced_neighbors.append((r - 1, c))
            if not is_wall((r + 1, c)) and is_wall((r + 1, c + 1)):
                forced_neighbors.append((r + 1, c))

        for fn in forced_neighbors:
            if not is_wall(fn):
                return True  # It is a jump point

        if (nr, nc) == goal:
            return True
        elif jump((nr, nc), (nr + dr, nc + dc), grid, dir, is_wall):
            return True
        return False

    def reconstruct_path(came_from, current):
        total_path = [current]
        while current in came_from:
            current = came_from[current]
            total_path.append(current)
            if current == start:
                break
        total_path.reverse()
        return total_path

    return jps_search(grid, start, goal)

