    def get_jump_point(r, c, dir):
        dr, dc = dir
        nr, nc = r + dr, c + dc
        while is_valid(nr, nc):
            if (dr and dc and
                is_valid(nr - dr, nc + dc) and not is_valid(nr + dr, nc + dc)) or \
                (is_valid(nr + dr, nc) and not is_valid(nr + dr, nc + dc)):
                return (nr, nc)
            nr += dr
            nc += dc
        return None

