import heapq
from collections import defaultdict

def solve(grid, start, goal):
    def is_valid(r, c):
        return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

    def heuristic(pos1, pos2):
        return abs(pos1[0] - pos2[0]) + abs(pos1[1] - pos2[1])

    def a_star_search(start, goal, reverse=False):
        visited = {}
        frontier = [(0, start)]
        while frontier:
            _, curr = heapq.heappop(frontier)
            if curr in visited:
                continue
            visited[curr] = None
            if curr == goal:
                return visited
            h = heuristic(curr, goal)
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = curr[0] + dr, curr[1] + dc
                if is_valid(nr, nc) and (reverse or (nr, nc) not in visited):
                    heapq.heappush(frontier, (h, (nr, nc)))
        return visited

    if not is_valid(*start) or not is_valid(*goal):
        return []

    if start == goal:
        return [start]

    start_to_goal = a_star_search(start, goal)
    if goal in start_to_goal:
        return reconstruct_path(start_to_goal, start, goal)

    goal_to_start = a_star_search(goal, start, True)
    merged = start_to_goal
    for node in goal_to_start:
        merged[node] = goal_to_start[node]

    mid = None
    for node in merged:
        if node in goal_to_start:
            if node in start_to_goal:
                mid = node
                break
    if mid:
        path1 = reconstruct_path(start_to_goal, start, mid)
        path2 = reconstruct_path(goal_to_start, mid, goal)
        path2.reverse()
        path1.extend(path2[1:])
        return path1

    return []

