    def heuristic(pos):
        return abs(pos[0] - goal[0]) + abs(pos[1] - goal[1])

    def astar(start, end_func):
        visited = {}
        queue = [(0, start)]
        came_from = {}

        while queue:
            _, current = heapq.heappop(queue)
            if end_func(current):
                path = []
                while current in came_from:
                    path.append(current)
                    current = came_from[current]
                path.reverse()
                return path
            if current in visited:
                continue
            visited[current] = True
            for dr, dc in dirs:
