def solve(grid: List[str], start: Tuple[int, int], goal: Tuple[int, int]) -> List[Tuple[int, int]]:
    if not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0])) or grid[start[0]][start[1]] == '#':
        return []
    if not (0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0])) or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # up, down, left, right

    def heuristic(a: Tuple[int, int], b: Tuple[int, int]) -> int:
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def a_star(start_pos: Tuple[int, int], goal_pos: Tuple[int, int], reverse: bool = False) -> Optional[Dict[Tuple[int, int], Tuple[int, int]]]:
        frontier = [(0, start_pos)]
        came_from = {}
        cost_so_far = {start_pos: 0}
        while frontier:
            current_cost, current = heapq.heappop(frontier)
            if current == goal_pos:
                break
            for dx, dy in directions:
                nx, ny = current[0] + dx, current[1] + dy
                if 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] == '.':
                    if reverse:
                        nx, ny = current[0] - dx, current[1] - dy  # Reverse direction
                    if (nx, ny) not in cost_so_far or cost_so_far[current] + 1 < cost_so_far[(nx, ny)]:
                        cost_so_far[(nx, ny)] = cost_so_far[current] + 1
                        priority = cost_so_far[(nx, ny)] + heuristic((nx, ny), goal_pos)
                        heapq.heappush(frontier, (priority, (nx, ny)))
                        came_from[(nx, ny)] = current
        return came_from

    came_from_start = a_star(start, goal)
    came_from_goal = a_star(goal, start, reverse=True)

    if not came_from_start or not came_from_goal:
        return []

    def reconstruct_path(came_from: Dict[Tuple[int, int], Tuple[int, int]], start: Tuple[int, int], end: Tuple[int, int]) -> List[Tuple[int, int]]:
        path = []
        current = end
        while current != start:
            path.append(current)
            current = came_from[current]
        path.append(start)
        path.reverse()
        return path

    def find_intersection(came_from1: Dict[Tuple[int, int], Tuple[int, int]], came_from2: Dict[Tuple[int, int], Tuple[int, int]]) -> Optional[Tuple[int, int]]:
        for node in came_from1:
            if node in came_from2:
                return node
        return None

    intersection = find_intersection(came_from_start, came_from_goal)
    if not intersection:
        return []

    path1 = reconstruct_path(came_from_start, start, intersection)
    path2 = reconstruct_path(came_from_goal, goal, intersection)
    path2.pop()  # Remove the intersection from the second path
    path2.reverse()
    return path1 + path2
