from heapq import heappush, heappop

def solve(grid, start, goal):
    if (
        not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0])) or
        not (0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0]))
    ):
        return []

    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    if start == goal:
        return [start]

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_free(row, col):
        return 0 <= row < len(grid) and 0 <= col < len(grid[0]) and grid[row][col] == '.'

    def heuristic(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def a_star(frontier, came_from, g_score, is_reversed):
        if not frontier:
            return None, None, None
        cost, current = heappop(frontier)
        if is_reversed:
            other_start = goal
        else:
            other_start = start
        if current in came_from:
            return None, None, None
        if current == other_start:
            return current, came_from, g_score

        for dr, dc in directions:
            nr, nc = current[0] + dr, current[1] + dc
            if is_free(nr, nc) and (nr, nc) not in g_score:
                new_cost = g_score[current] + 1
                heur = heuristic((nr, nc), other_start)
                heappush(frontier, (new_cost + heur, (nr, nc)))
                g_score[(nr, nc)] = new_cost
                came_from[(nr, nc)] = current
        return None, came_from, g_score

    forward_queue = []
    heappush(forward_queue, (heuristic(start, goal), start))
    forward_came_from = {start: None}
    forward_g = {start: 0}

    reverse_queue = []
    heappush(reverse_queue, (heuristic(goal, start), goal))
    reverse_came_from = {goal: None}
    reverse_g = {goal: 0}

    meet = None
    while forward_queue and reverse_queue:
        forward_meet, forward_came, forward_g = a_star(forward_queue, forward_came_from, forward_g, False)
        if forward_meet:
            meet = forward_meet
            break
        reverse_meet, reverse_came, reverse_g = a_star(reverse_queue, reverse_came_from, reverse_g, True)
        if reverse_meet:
            meet = reverse_meet
            break

    if not meet:
        return []

    path = []
    step = meet
    while step is not None:
        path.append(step)
        step = forward_came[step]
    path.reverse()

    step = forward_g[meet]
    step = reverse_came[meet]
    while step is not None:
        path.append(step)
        step = reverse_came[step]

    return path
