    rows = len(grid)
    cols = len(grid[0])

    # Check if start or goal is a wall or out of bounds
    if not (0 <= start[0] < rows and 0 <= start[1] < cols and
            0 <= goal[0] < rows and 0 <= goal[1] < cols and
            grid[start[0]][start[1]] != '#' and grid[goal[0]][goal[1]] != '#'):
