                neighbor = (current[0] + dx, current[1] + dy)
                if (0 <= neighbor[0] < rows and 0 <= neighbor[1] < cols and grid[neighbor[0]][neighbor[1]] != '#'):
                    tentative_g = g_score[current] + 1
                    if g_score.get(neighbor, float('inf')) > tentative_g:
                        g_score[neighbor] = tentative_g
                        f_score[neighbor] = tentative_g + heuristic(neighbor, goal)
                        heapq.heappush(open_set, (f_score[neighbor], neighbor))
                        came_from[neighbor] = current
        return None

    forward_path = astar(start, goal, grid)
    backward_path = astar(goal, start, grid)

    if forward_path:
        return [start] + forward_path

    # Try to recombine forward and backward paths
    forward_set = set()
    current = start
    forward_set.add(current)
    for p in forward_path:
        forward_set.add(p)

    backward_path.reverse()
