import heapq
from collections import deque

def solve(grid, start, goal):
    def get_neighbors(pos):
        r, c = pos
        neighbors = [(r + dr, c + dc) for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]]
        return [(nr, nc) for nr, nc in neighbors if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and grid[nr][nc] == '.']

    def is_goal(pos):
        return pos == goal

    def heuristic(pos):
        r, c = pos
        gr, gc = goal
        return abs(r - gr) + abs(c - gc)

    def a_star_search(start_point, goal_check, get_goal):
        open_set = [(0, start_point)]
        came_from = {}
        cost_so_far = {start_point: 0}
        frontier = {start_point}

        while open_set:
            _, current = heapq.heappop(open_set)
            frontier.remove(current)
            if current in cost_so_far and cost_so_far[current] < (cost_so_far.get(current, float('inf'))):
                continue
            if goal_check(current):
                path = []
                while current in came_from:
                    path.append(current)
                    current = came_from[current]
                path.reverse()
                return path + [get_goal()]
            for next_pos in get_neighbors(current):
                new_cost = cost_so_far[current] + 1
                if next_pos not in cost_so_far or new_cost < cost_so_far[next_pos]:
                    cost_so_far[next_pos] = new_cost
                    priority = new_cost + heuristic(next_pos)
                    heapq.heappush(open_set, (priority, next_pos))
                    came_from[next_pos] = current
                    frontier.add(next_pos)
        return None

    sr, sc = start
    gr, gc = goal

    if not (0 <= sr < len(grid) and 0 <= sc < len(grid[0])) or grid[sr][sc] == '#':
        return []
    if not (0 <= gr < len(grid) and 0 <= gc < len(grid[0])) or grid[gr][gc] == '#':
        return []
    if start == goal:
        return [start]

