import heapq

def solve(grid, start, goal):
    def is_valid(pos):
        r, c = pos
        return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

    def neighbors(pos):
        r, c = pos
        return [(nr, nc) for (nr, nc) in [(r-1,c), (r+1,c), (r,c-1), (r,c+1)] if is_valid((nr, nc))]

    def heuristic(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    start, goal = tuple(start), tuple(goal)
    if not is_valid(start) or not is_valid(goal):
        return []

    if start == goal:
        return [start]

    forward = {
        'open': [(heuristic(start, goal), (0, 0, 0, start))],
        'came_from': {},
        'cost': {start: 0},
        'found': False,
        'goal': None
    }

    backward = {
        'open': [(heuristic(goal, start), (0, 0, 0, goal))],
        'came_from': {},
        'cost': {goal: 0},
        'found': False,
        'goal': None
    }

    def a_star(start_state, end_state, neighbors):
        open_heap = start_state['open']
        came_from = start_state['came_from']
        cost = start_state['cost']
        goal = end_state['goal'] if end_state['goal'] else start_state['goal']
        found = False
        while open_heap:
            _, (f, g, _, pos) = heapq.heappop(open_heap)
            if pos == goal:
                end_state['goal'] = pos
                found = True
                end_state['came_from'] = came_from
                end_state['cost'] = cost
                end_state['found'] = True
                return
            if pos in came_from:
                continue
            came_from[pos] = None
            for n_pos in neighbors(pos):
                n_cost = g + 1
                if n_pos not in cost or n_cost < cost[n_pos]:
                    cost[n_pos] = n_cost
                    h = heuristic(n_pos, goal)
                    heapq.heappush(open_heap, (f + 1, (n_cost + h, n_cost, 0, n_pos)))
                    came_from[n_pos] = pos

    while forward['open'] and backward['open']:
        a_star(forward, backward, neighbors)
        if backward['found']:
            return _reconstruct_path(forward['came_from'], backward['came_from'], start, backward['goal'])
        a_star(backward, forward, neighbors)
        if forward['found']:
            return _reconstruct_path(backward['came_from'], forward['came_from'], goal, forward['goal'])
    return []

def _reconstruct_path(reverse_came_from, forward_came_from, start, goal):
    path = []
    current = goal
    while current:
        path.append(current)
        if current not in reverse_came_from:
            break
        current = reverse_came_from[current]
    if path[-1] != start:
        return []
    path.reverse()
    current = path[-1]
    while current and current in forward_came_from:
        current = forward_came_from[current]
        if current:
            path.append(current)
    if path[0] != start:
        return []
    return path
