def solve(grid, start, goal):
    if start == goal:
        return [start]
    if not is_free(grid, *start) or not is_free(grid, *goal):
        return []

    rows, cols = len(grid), len(grid[0])

    def get_neighbors(r, c):
        directions = [(-1,0), (1,0), (0,-1), (0,1)]
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                yield (nr, nc)

    def heuristic(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def search(frontier, visited, came_from, other_visited):
        if not frontier:
            return None
        cost, (current, path) = heapq.heappop(frontier)
        if current in other_visited:
            full_path = path + list(reversed(other_visited[current][1]))
            return full_path
        for neighbor in get_neighbors(*current):
            if neighbor not in visited:
                new_path = path + [neighbor]
                visited[neighbor] = (cost + 1, new_path)
                came_from[neighbor] = current
                heapq.heappush(frontier, (cost + 1 + heuristic(neighbor, goal if is_forward else start), (neighbor, new_path)))
        return None

    def is_free(grid, r, c):
        return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

    frontier_start = []
    frontier_goal = []
    heapq.heappush(frontier_start, (heuristic(start, goal), (start, [start])))
    heapq.heappush(frontier_goal, (heuristic(goal, start), (goal, [goal])))

    came_from_start = {start: None}
    came_from_goal = {goal: None}

    visited_start = {start: (0, [start])}
    visited_goal = {goal: (0, [goal])}

    is_forward = True

    while frontier_start and frontier_goal:
        if is_forward:
            result = search(frontier_start, visited_start, came_from_start, visited_goal)
        else:
            result = search(frontier_goal, visited_goal, came_from_goal, visited_start)
        is_forward = not is_forward
        if result:
            return result
    return []

