from collections import deque

def solve(grid, start, goal):
    rows = len(grid)
    if rows == 0:
        return []
    cols = len(grid[0])
    if start == goal and grid[start[0]][start[1]] == '.':
        return [start]
    if (grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#'):
        return []

    def neighbors(pos):
        r, c = pos
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                yield (nr, nc)

    def bfs(pos, forward=True):
        q = deque()
        q.append(pos)
        came_from = {pos: None}
        while q:
            current = q.popleft()
            for next_pos in neighbors(current):
                if next_pos not in came_from:
                    came_from[next_pos] = current
                    q.append(next_pos)
                    if next_pos in other_set:
                        return (came_from, next_pos)
        return (came_from, None)

    forward_set = set([start])
    backward_set = set([goal])
    forward_path = {start: None}
    backward_path = {goal: None}

    forward = True
    meet_pos = None
    while forward_set and backward_set and meet_pos is None:
        if forward:
            forward_data = bfs(start, forward=True)
            forward_path, meet_pos = forward_data
            if meet_pos:
                break
            forward_set = set(forward_path.keys()) & backward_set
        else:
            backward_data = bfs(goal, forward=False)
            backward_path, meet_pos = backward_data
            if meet_pos:
                break
            backward_set = set(backward_path.keys()) & forward_set
        forward = not forward

    if meet_pos is None:
        return []

    # Build path
    path = []
    current = goal
    while current is not None:
        path.append(current)
        current = backward_path[current]
    path.reverse()
    current = path[-1]
    while current != start:
        path.append(current)
        current = forward_path[current]
    return path
