from collections import deque

def solve(grid, start, goal):
    if not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0]) and grid[start[0]][start[1]] == '.'):
        return []
    if not (0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0]) and grid[goal[0]][goal[1]] == '.'):
        return []
    if start == goal:
        return [start]

    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def bfs(from_queue, to_visited, path_map):
        r, c = from_queue.popleft()
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if (0 <= nr < rows and 0 <= nc < cols and
                grid[nr][nc] == '.' and (nr, nc) not in from_visited and (nr, nc) not in path_map):
                from_queue.append((nr, nc))
                from_visited.add((nr, nc))
                path_map[(nr, nc)] = (r, c)
                if (nr, nc) in to_visited:
                    return (r, c), (nr, nc)
        return None, None

    forward_queue = deque([start])
    forward_visited = {start}
    backward_queue = deque([goal])
    backward_visited = {goal}
    forward_path = {}
    backward_path = {}

    while forward_queue and backward_queue:
        result = bfs(forward_queue, forward_visited, backward_path)
        if result[0] is not None:
            meet1, meet2 = result
            return build_path(start, goal, meet1, meet2, forward_path, backward_path)
        result = bfs(backward_queue, backward_visited, forward_path)
        if result[0] is not None:
            meet1, meet2 = result
            return build_path(start, goal, meet1, meet2, forward_path, backward_path)

    return []

def build_path(start, goal, meet1, meet2, forward_path, backward_path):
    path = [goal]
    curr = goal
    while curr != start:
        if curr in backward_path:
            curr = backward_path[curr]
            path.append(curr)
        else:
            break
    path.reverse()
    curr = meet1
    while curr in forward_path:
        curr = forward_path[curr]
        path.append(curr)
    path.reverse()
    return path[:path.index(goal)+1]
