from collections import deque

def solve(grid, start, goal):
    if not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0])):
        return []
    if not (0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0])):
        return []
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    rows = len(grid)
    cols = len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def bfs(starts, is_forward):
        q = deque()
        for s in starts:
            q.append(s)
        came_from = {}
        for s in starts:
            came_from[s] = None
        while q:
            current = q.popleft()
            for dr, dc in directions:
                if is_forward:
                    nr, nc = current[0] + dr, current[1] + dc
                else:
                    nr, nc = current[0] - dr, current[1] - dc
                next_cell = (nr, nc)
                if (0 <= nr < rows and 0 <= nc < cols and
                        grid[nr][nc] == '.' and next_cell not in came_from):
                    came_from[next_cell] = current
                    q.append(next_cell)
                    if next_cell == (goal if is_forward else start):
                        return came_from
        return None

    forward = bfs([start], is_forward=True)
    if not forward:
        return []
    backwards = bfs([goal], is_forward=False)
    if not backwards:
        return []

    intersection = set(forward).intersection(backwards)
    if not intersection:
        return []

    common = None
    for node in intersection:
        if node in forward and node in backwards:
            common = node
            break

    # Build path from start to common
    path = []
    current = common
    while current:
        path.append(current)
        current = forward[current]
    path.reverse()

    # Build path from common to goal
    current = backwards[common]
    while current:
        path.append(current)
        current = backwards[current]

    return path
