from typing import List, Tuple

def solve(grid: List[str], start: Tuple[int, int], goal: Tuple[int, int]) -> List[Tuple[int, int]]:
    if start == goal:
        return [start]

    rows, cols = len(grid), len(grid[0])

    def is_valid(r: int, c: int) -> bool:
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def bfs(start_pos, end_pos):
        queue = deque([(start_pos, [start_pos])])
        visited = {start_pos}
        while queue:
            (r, c), path = queue.popleft()
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if (nr, nc) == end_pos:
                    return path + [(nr, nc)]
                if is_valid(nr, nc) and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    queue.append(((nr, nc), path + [(nr, nc)]))
        return None

    # Check if start or goal is a wall
    if not is_valid(*start) or not is_valid(*goal):
        return []

    path_from_start = bfs(start, goal)
    path_from_goal = bfs(goal, start)

    return path_from_start if path_from_start else path_from_goal
