def solve(grid, start, goal):
    if start == goal:
        return [start]

    rows, cols = len(grid), len(grid[0])

    # Check if start or goal are walls
    if (
        not (0 <= start[0] < rows and 0 <= start[1] < cols and grid[start[0]][start[1]] == '.')
        or not (0 <= goal[0] < rows and 0 <= goal[1] < cols and grid[goal[0]][goal[1]] == '.')
    ):
        return []

    directions = [(-1,0), (1,0), (0,-1), (0,1)]

    def dfs(current, depth, visited, path):
        if current == goal:
            return path[:]
        if depth <= 0 or current in visited:
            return None
        for dr, dc in directions:
            nr, nc = current[0] + dr, current[1] + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                new_visited = visited | {current}
                new_path = path + [(nr, nc)]
                result = dfs((nr, nc), depth - 1, new_visited, new_path)
                if result:
                    return result
        return None

    max_depth = rows * cols  # Worst case for path length
    for depth in range(1, max_depth + 1):
        visited = set()
        result = dfs(start, depth, visited, [start])
        if result:
            return result
    return []
