def solve(grid, start, goal):
    if (
        not is_valid(grid, start[0], start[1]) or 
        not is_valid(grid, goal[0], goal[1])
    ):
        return []

    if start == goal:
        return [start]

    rows, cols = len(grid), len(grid[0])

    def neighbors(r, c):
        return [(r + dr, c + dc) for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)] 
                if 0 <= r + dr < rows and 0 <= c + dc < cols and grid[r + dr][c + dc] == '.']

    def is_blocked(r, c):
        return not (0 <= r < rows and 0 <= c < cols and grid[r][c] == '.')

    def find_next_jump(r, c, direction_r, direction_c):
        if is_blocked(r, c):
            return None
        if (r, c) == goal:
            return (r, c)
        new_r, new_c = r + direction_r, c + direction_c
        if is_blocked(new_r, new_c):
            return None
        # If changing direction could lead to a forced neighbor, add them
        if direction_r != 0 and direction_c != 0:
            # Diagonal move, check orthogonal steps
            if is_blocked(r + direction_r, c) or is_blocked(r, c + direction_c):
                return (r, c)
            if (r + direction_r, c + direction_c) == goal:
                return (r + direction_r, c + direction_c)
            res = find_next_jump(r + direction_r, c + direction_c, direction_r, 0)
            if res:
                return res
            res = find_next_jump(r + direction_r, c + direction_c, 0, direction_c)
            if res:
                return res
            return find_next_jump(r + direction_r, c + direction_c, direction_r, direction_c)
        else:
            # Horizontal/vertical move, check for forced neighbors
            if direction_r != 0:
                if is_blocked(r, c - 1) or is_blocked(r, c + 1):
                    return (r, c)
            elif direction_c != 0:
                if is_blocked(r - 1, c) or is_blocked(r + 1, c):
                    return (r, c)
            return find_next_jump(r + direction_r, c + direction_c, direction_r, direction_c)

    def jps_search():
        open_set = [(0, start)]
        came_from = {}
