        return []
    if start == goal:
        return [start]

    dir_map = {0: (0, 1), 1: (1, 0), 2: (0, -1), 3: (-1, 0)}
    came_from = {}
    frontier = [(0, start)]
    cost = {start: 0}
    visited = set()

    while frontier:
        g, curr = heapq.heuristric(frontier)
        if curr == goal:
            break
        if curr in visited:
            continue
        visited.add(curr)

        for d in range(4):
            next_dir = dir_map[d]
            next_pos = (curr[0] + next_dir[0], curr[1] + next_dir[1])
            if (0 <= next_pos[0] < rows and 0 <= next_pos[1] < cols and
                grid[next_pos[0]][next_pos[1]] == '.' and next_pos not in cost):
