import heapq

def neighbors(pos, grid):
    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # up, down, left, right
    for dr, dc in directions:
        r, c = pos[0] + dr, pos[1] + dr
        if 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.':
            yield (r, c)

def manhattan(p1, p2):
    return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

def jump(grid, pos, goal, direction):
    r, c = pos
    dr, dc = direction
    if not (0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'):
        return None

    if (r, c) == goal:
        return (r, c)

    # Check forward
    next_r, next_c = r + dr, c + dc
    if not (0 <= next_r < len(grid) and 0 <= next_c < len(grid[0]) and grid[next_r][next_c] == '.'):
        return None

    if dr != 0 and dc != 0:  # Diagonal movement
        # Vertical first
        result = jump(grid, (r + dr, c), goal, (dr, 0))
        if result:
            return result
        # Horizontal
        result = jump(grid, (r, c + dc), goal, (0, dc))
        if result:
            return result
    else:
        return jump(grid, (next_r, next_c), goal, direction)

    return None

def solve(grid, start, goal):
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    def heuristic(pos):
        return manhattan(pos, goal)

    open_set = [(0, heuristic(start), 0, start, None)]  # (f, h, g, pos, direction)
    parent = {}
    visited = set()

    while open_set:
        _, _, g, current, dir = heapq.heappop(open_set)
        if current == goal:
            path = []
            while current in parent:
                path.append(current)
                current = parent[current]
            path.append(start)
            return path[::-1]

        if current in visited:
            continue
        visited.add(current)

        for next_dir in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            jump_pos = jump(grid, current, goal, next_dir)
            if jump_pos and jump_pos != current and jump_pos not in visited:
                new_g = g + manhattan(current, jump_pos)
                heapq.heappush(open_set, (new_g + heuristic(jump_pos), heuristic(jump_pos), new_g, jump_pos, next_dir))
                parent[jump_pos] = current

    return []
