def solve(grid, start, goal):
    if start == goal:
        return [start]

    rows = len(grid)
    cols = len(grid[0])

    if (start[0] < 0 or start[0] >= rows or start[1] < 0 or start[1] >= cols or
        goal[0] < 0 or goal[0] >= rows or goal[1] < 0 or goal[1] >= cols or
        grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#'):
        return []

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    visited = [[False for _ in range(cols)] for _ in range(rows)]
    parent = [[None for _ in range(cols)] for _ in range(rows)]
    pq = [(0, 0, start[0], start[1])]  # (h, g, row, col)

    def heuristic(r, c):
        return abs(goal[0] - r) + abs(goal[1] - c)

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def jump(r, c, dr, dc):
        if not is_valid(r, c):
            return None
        if (r, c) == goal:
            return (r, c)
        visited[r][c] = True
        for nr, nc in [(r + dr, c + dc), (r + dr, c), (r, c + dc)]:
            if is_valid(nr, nc) and not visited[nr][nc]:
                if (dr, dc) == (0, 1):
                    if jump(r, c + 1, 0, 1):
                        return jump(r, c + 1, 0, 1)
                elif (dr, dc) == (1, 0):
                    if jump(r + 1, c, 1, 0):
                        return jump(r + 1, c, 1, 0)
                elif (dr, dc) == (-1, 0):
                    if jump(r - 1, c, -1, 0):
                        return jump(r - 1, c, -1, 0)
                elif (dr, dc) == (0, -1):
                    if jump(r, c - 1, 0, -1):
                        return jump(r, c - 1, 0, -1)
        return None

    heapq.heapify(pq)
    while pq:
        h, g, r, c = heapq.heappop(pq)
        if (r, c) == goal:
            path = []
            while (r, c) != start:
                path.append((r, c))
                pr, pc = parent[r][c]
                r, c = pr, pc
            path.append(start)
            return path[::-1]

        if visited[r][c]:
