    rows = len(grid)
    cols = len(grid[0])

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    # Jump Point Search
    def jps(grid, start, goal):
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # up, down, left, right

        # BFS with JPS logic, for simplicity
        def jump(r, c, dr, dc, visited):
            if not (0 <= r < rows and 0 <= c < cols):
                return None
            if grid[r][c] == '#' or (r, c) in visited:
                return None
            if (r, c) == goal:
                return (r, c)
            visited.add((r, c))
            # Jump diagonally towards the direction
            next_r, next_c = r + dr, c + dc
            result = jump(next_r, next_c, dr, dc, visited)
            if result:
                return result
            return None

        visited = set()
        queue = deque()
        queue.append((start[0], start[1], None))
        came_from = {}

        while queue:
            r, c, parent = queue.popleft()
            if (r, c) == goal:
                # Reconstruct path from came_from
                path = []
                current = (r, c)
                while current:
                    path.append(current)
                    current = came_from.get(current)
