def solve(grid, start, goal):
    from collections import deque

    def get_neighbors(x, y):
        neighbors = []
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < len(grid) and 0 <= ny < len(grid[0]) and grid[nx][ny] == '.':
                neighbors.append((nx, ny))
        return neighbors

    def bfs(start_pos, goal_pos):
        queue = deque([(start_pos, [start_pos])])
        visited = set([start_pos])
        while queue:
            (x, y), path = queue.popleft()
            if (x, y) == goal_pos:
                return path
            for nx, ny in get_neighbors(x, y):
                if (nx, ny) not in visited:
                    visited.add((nx, ny))
                    queue.append(((nx, ny), path + [(nx, ny)]))
        return []

    def is_free(pos):
        x, y = pos
        return 0 <= x < len(grid) and 0 <= y < len(grid[0]) and grid[x][y] == '.'

    def directional_jump(points, rank, dir, diff):
        x0, y0 = points[rank]
        x1, y1 = points[rank + 1]
        dx, dy = diff
        px, py = x0 + dx, y0 + dy
        if not is_free((px, py)) or (px, py) == (x1, y1):
            return [(x0, y0), (x1, y1)]
        res = [points[rank]]
        while (x0, y0) != (x1, y1):
            x0 += dx
            y0 += dy
            if not is_free((x0, y0)):
                break
            res.append((x0, y0))
        return res

    def horizontal_search(x, y, dx):
        path = [(x, y)]
        while True:
            if dx == 1:
                nx, ny = x, y + 1
            elif dx == -1:
                nx, ny = x, y - 1
            else:
                nx, ny = x, y
            x += dx
            if not is_free((x, y)) or (x, y) == (goal[0], goal[1]):
                break
            if (nx, ny) == goal or not is_free((nx, ny)):
                path.append((x, y))
                break
            if grid[x + dx][y][0] == '#' or (x + dx, y) == goal:
                path.append((x, y))
                break
