def solve(grid, start, goal):
    if start == goal:
        return [start]

    rows = len(grid)
    cols = len(grid[0])

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    # Directions: right, down, left, up
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    dir_names = ['right', 'down', 'left', 'up']

    # Direction to vector
    def get_dir(dx, dy):
        if dx == 0 and dy > 0:
            return ('right', (0,1))
        elif dx == 0 and dy < 0:
            return ('left', (0,-1))
        elif dx > 0 and dy == 0:
            return ('down', (1,0))
        elif dx < 0 and dy == 0:
            return ('up', (-1,0))
        return (None, None)

    # Predecessor for a direction
    def opposite_dir(d):
        op_dir = {'right': 'left', 'left': 'right', 'up': 'down', 'down': 'up'}
        return op_dir[d]

    # Jump point search
    def is_corner(r, c, dir_r, dir_c):
        if not is_valid(r + dir_r, c + dir_c) or not is_valid(r, c + dir_c) or not is_valid(r + dir_r, c):
            return False
        return is_valid(r + dir_r, c + dir_c) and is_valid(r, c + dir_c) and is_valid(r + dir_r, c)

    def is_straight_line(r, c, dir_r, dir_c):
        for step in range(2, max(rows, cols)+1):
            nr, nc = r + dir_r * step, c + dir_c * step
            if not is_valid(nr, nc):
                return False
