import heapq

def solve(grid, start, goal):
    if start == goal:
        return [start]

    rows, cols = len(grid), len(grid[0])
    if (not (0 <= start[0] < rows and 0 <= start[1] < cols and
             grid[start[0]][start[1]] == '.')) or \
       (not (0 <= goal[0] < rows and 0 <= goal[1] < cols and
             grid[goal[0]][goal[1]] == '.')):
        return []

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def get_neighbors(r, c):
        neighbors = []
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc):
                neighbors.append((nr, nc))
        return neighbors

    def heuristic(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def jump(r, c, dir_r, dir_c):
        if not is_valid(r, c):
            return None
        if (r, c) == goal:
            return (r, c)
        # Check if the cell is forced
        if dir_r != 0 and dir_c != 0:  # Diagonal direction (not used here)
            pass
        elif dir_r != 0:
            # Vertical direction
            if (is_valid(r + dir_r, c) and not is_valid(r + dir_r, c - 1) and
                (r + dir_r, c - 1) != goal):
                return (r, c)
            if (is_valid(r + dir_r, c) and not is_valid(r + dir_r, c + 1) and
                (r + dir_r, c + 1) != goal):
                return (r, c)
            return jump(r + dir_r, c, dir_r, dir_c)
        elif dir_c != 0:
            # Horizontal direction
            if (is_valid(r, c + dir_c) and not is_valid(r - 1, c + dir_c) and
                (r - 1, c + dir_c) != goal):
                return (r, c)
            if (is_valid(r, c + dir_c) and not is_valid(r + 1, c + dir_c) and
                (r + 1, c + dir_c) != goal):
                return (r, c)
            return jump(r, c + dir_c, dir_r, dir_c)
        return None

    def get_jump_neighbors(r, c):
        neighbors = []
        for dr, dc in directions:
            jpn = jump(r + dr, c + dc, dr, dc)
            if jpn and jpn != (r, c):
                neighbors.append(jpn)
        return neighbors

    pq = [(heuristic(start, goal), 0, start, None)]
    visited = set()
    parent = {}

    while pq:
        h, g, current, prev = heapq.heappop(pq)
        if current in visited:
            continue
        visited.add(current)
        parent[current] = prev
        if current == goal:
            break
        for dr, dc in directions:
            nr, nc = current[0] + dr, current[1] + dc
            if is_valid(nr, nc) and (nr, nc) not in visited:
                jpn = jump(nr, nc, dr, dc)
                if jpn and jpn not in visited:
                    new_g = g + 1
                    new_h = heuristic(jpn, goal)
                    heapq.heappush(pq, (new_g + new_h, new_g, jpn, current))

    if goal not in parent:
        return []

    path = []
    curr = goal
    while curr is not None:
        path.append(curr)
        curr = parent[curr]
    return path[::-1]
