import heapq

class PriorityQueue:
    def __init__(self):
        self.elements = []

    def empty(self):
        return len(self.elements) == 0

    def put(self, item, priority):
        heapq.heappush(self.elements, (priority, item))

    def get(self):
        return heapq.heappop(self.elements)[1]


def solve(grid, start, goal):
    if not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0])):
        return []
    if not (0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0])):
        return []
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    if start == goal:
        return [start]

    def is_valid(pos):
        r, c = pos
        return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

    def get_neighbors(pos):
        r, c = pos
        return [(r+dr, c+dc) for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)] if is_valid((r+dr, c+dc))]

    def get_jump_point(pos, direction, parent):
        r, c = pos
        dr, dc = direction

        # Check if the current position is a jump point
        # Check diagonals
        if dr != 0 and dc != 0:
            for ddr, ddc in [(-1,-1), (-1,1), (1,-1), (1,1)]:
                nr, nc = r + ddr, c + ddc
                if is_valid((nr, nc)):
                    if (r + dr + ddr, c + dc + ddc) not in visited or (nr, nc) == goal:
                        return (r, c)

        # If moving in direction, check for forced neighbors
        dir_map = {(-1,0): [(-1,-1), (-1,1)],
                   (1,0): [(1,-1), (1,1)],
                   (0,-1): [(-1,-1), (1,-1)],
                   (0,1): [(-1,1), (1,1)]}

        if direction in dir_map:
            for dr2, dc2 in dir_map[direction]:
                nr, nc = r + dr2, c + dc2
                if is_valid((nr, nc)) and (r + dr + dr2, c + dc + dc2) not in visited and (r + dr + dr2, c + dc + dc2) != parent:
                    return (r, c)

        # Continue jumping
        nr, nc = r + dr, c + dc
        if not is_valid((nr, nc)):
            return None
        if (nr, nc) == goal:
            return (nr, nc)
        return get_jump_point((nr, nc), direction, pos)

    def jps_search():
        came_from = {}
        cost_so_far = {}
        pq = PriorityQueue()
        pq.put(start, 0)
        came_from[start] = None
        cost_so_far[start] = 0

        while not pq.empty():
            current = pq.get()

            if current == goal:
                break

            for direction in [(0,1), (1,0), (0,-1), (-1,0)]:
                r, c = current
                dr, dc = direction
                if (r + dr, c + dc) in came_from:
                    continue
                jump_point = get_jump_point(current, direction, came_from.get(current))
                if jump_point and is_valid(jump_point):
                    new_cost = cost_so_far[current] + 1
                    if jump_point not in cost_so_far or new_cost < cost_so_far[jump_point]:
                        cost_so_far[jump_point] = new_cost
                        priority = new_cost
                        pq.put(jump_point, priority)
                        came_from[jump_point] = current

