def solve(grid, start, goal):
    if not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0]) and
            0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0])):
        return []

    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    if start == goal:
        return [start]

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def heuristic(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def a_star_search(start, goal, reverse=False):
        open_set = []
        heapq.heappush(open_set, (0, start))
        came_from = {}
        cost_so_far = {start: 0}

        while open_set:
            _, current = heapq.heappop(open_set)

            if current == goal:
                break

            for dx, dy in directions:
                if reverse:
                    nx, ny = current[0] + dx, current[1] + dy
                else:
                    nx, ny = current[0] - dx, current[1] - dy
                if 0 <= nx < len(grid) and 0 <= ny < len(grid[0]) and grid[nx][ny] == '.':
                    new_cost = cost_so_far[current] + 1
                    if (nx, ny) not in cost_so_far or new_cost < cost_so_far[(nx, ny)]:
                        cost_so_far[(nx, ny)] = new_cost
                        priority = new_cost + heuristic((nx, ny), goal)
                        heapq.heappush(open_set, (priority, (nx, ny)))
                        came_from[(nx, ny)] = current

        return came_from

    forward_path = a_star_search(start, goal)
    backward_path = a_star_search(goal, start, reverse=True)

    if not forward_path and not backward_path:
        return []

    def reconstruct_path(forward, goal, reverse=False):
        if goal not in forward:
            return None
        path = [goal]
        while path[-1] != start:
            next_node = forward.get(path[-1])
            if next_node is None:
                return None
            path.append(next_node)
            if reverse and path[-2] == path[-1]:
                return None
        return path[::-1]

    path = reconstruct_path(forward_path, goal)
    if path:
        return path

    path = reconstruct_path(backward_path, start, reverse=True)
    if path:
