import heapq

class BidirectionalAStar:
    def __init__(self):
        self.offsets = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # up, down, left, right

    def heuristic(self, a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def get_neighbors(self, pos, grid):
        r, c = pos
        rows, cols = len(grid), len(grid[0])
        neighbors = []
        for dr, dc in self.offsets:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                neighbors.append((nr, nc))
        return neighbors

    def reconstruct_path(self, came_from, start, goal, forward):
        path = []
        current = goal if forward else start
        while current in came_from:
            path.append(current)
            current = came_from[current]
        if path:
            path.reverse()
        if path and path[0] == start:
            return path
        return []

    def a_star(self, grid, start, goal, forward=True):
        rows, cols = len(grid), len(grid[0])
        goal_dir = 1 if forward else -1
        open_set = [(self.heuristic(start, goal), start)]
        came_from = {}
        costs = {start: 0}
        visited = set()

        while open_set:
            _, current = heapq.heappop(open_set)
            if current == (start[0] + goal_dir * (goal[0] - start[0]), start[1] + goal_dir * (goal[1] - start[1])):
                break
            if current in visited:
                continue
            visited.add(current)
            for neighbor in self.get_neighbors(current, grid):
                if neighbor in visited:
                    continue
                new_cost = costs[current] + 1
                if neighbor not in costs or new_cost < costs[neighbor]:
                    costs[neighbor] = new_cost
                    heapq.heappush(open_set, (new_cost + self.heuristic(neighbor, goal), neighbor))
                    came_from[neighbor] = current
        return came_from, visited

    def solve(self, grid, start, goal):
        if start == goal and grid[start[0]][start[1]] == '.':
            return [start]
        if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
            return []
        forward_came_from, forward_visited = self.a_star(grid, start, goal, forward=True)
        backward_came_from, backward_visited = self.a_star(grid, goal, start, forward=False)
        for node in forward_visited.intersection(backward_visited):
            forward_path = self.reconstruct_path(forward_came_from, start, node, forward=True)
            backward_path = self.reconstruct_path(backward_came_from, goal, node, forward=False)
            if forward_path and backward_path:
                full_path = forward_path + backward_path[1:]
                if all(grid[r][c] == '.' for r, c in full_path):
                    return full_path
        return []

def solve(grid, start, goal):
    return BidirectionalAStar().solve(grid, start, goal)
