    directions = [(-1,0), (1,0), (0,-1), (0,1)]

    def iddfs(start, goal, max_depth):
        for depth in range(1, max_depth + 1):
            visited = set()
            stack = [(start, [start], visited.copy())]
            while stack:
                pos, path, v = stack.pop()
                if pos == goal:
                    return path
                if len(path) < depth:
                    for dr, dc in directions:
