import heapq

def solve(grid, start, goal):
    if start == goal:
        return [start]
    if not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0]) and
            grid[start[0]][start[1)] == '.'):
        return []
    if not (0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0]) and
            grid[goal[0]][goal[1]] == '.'):
        return []

    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    frontier = [(0, 0, start, None, None)]
    heapq.heapify(frontier)
    came_from = {}
    cost = {start: 0}

    while frontier:
        _, _, (r, c), pr, pc = heapq.heappop(frontier)
        if (r, c) == goal:
            break
        for dr, dc in dirs:
            if dr == 0 and dc == 0:
                continue
            if abs(dr) == 1 and pr is not None and pr == r - dr and pc == c - dc:
                continue
            if abs(dc) == 1 and pc is not None and pc == c - dc and pr == r - dr:
                continue
            nr, nc = r, c
            pr0, pc0 = r - dr, c - dc
            while True:
                nr += dr
                nc += dc
                if not (0 <= nr < len(grid) and 0 <= nc < len(grid[0])):
                    break
                if grid[nr][nc] == '#':
                    break
                if nr == pr0 and nc == pc0:
                    break
            if (nr - dr, nc - dc) == (pr0, pc0):
                pass
            else:
                pr0 = pr
                pc0 = pc
            if (nr - dr, nc - dc) == (r, c):
                continue
            if (nr - dr, nc - dc) not in came_from or cost[(r, c)] + 1 < cost[(nr - dr, nc - dc)]:
                came_from[(nr - dr, nc - dc)] = (r, c)
                cost[(nr - dr, nc - dc)] = cost[(r, c)] + 1
                h = abs(nr - dr - goal[0]) + abs(nc - dc - goal[1])
                heapq.heappush(frontier, (cost[(nr - dr, nc - dc)] + h, h, (nr - dr, nc - dc), r, c))

    if goal not in came_from:
        return []

    path = [goal]
    while path[-1] != start:
        path.append(came_from[path[-1]])
    return path[::-1]
