def solve(grid, start, goal):
    if start == goal:
        return [start]

    rows = len(grid)
    if rows == 0:
        return []

    cols = len(grid[0])

    def is_wall(r, c):
        return r < 0 or r >= rows or c < 0 or c >= cols or grid[r][c] == '#'

    if is_wall(*start) or is_wall(*goal):
        return []

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # up, down, left, right

    def dfs(limit, current, path, visited):
        if current == goal:
            return path
        if len(path) - 1 > limit:
            return None
        for dr, dc in directions:
            nr, nc = current[0] + dr, current[1] + dc
            next_cell = (nr, nc)
            if not is_wall(nr, nc) and next_cell not in visited:
                visited.add(next_cell)
                result = dfs(limit, next_cell, path + [next_cell], visited)
                if result is not None:
                    return result
                visited.remove(next_cell)
        return None

    def iddfs():
        depth = 0
        visited = set([start])
        while True:
            result = dfs(depth, start, [start], visited.copy())
            if result is not None:
                return result
            if depth > rows * cols:
                return []
            depth += 1

    return iddfs()
