import heapq

def solve(grid, start, goal):
    if not grid or not grid[0]:
        return []
    rows, cols = len(grid), len(grid[0])

    def is_wall(pos):
        r, c = pos
        return not (0 <= r < rows and 0 <= c < cols) or grid[r][c] == '#'

    def is_free(pos):
        r, c = pos
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # Up, Down, Left, Right
    dir_to_index = {(dr, dc): i for i, (dr, dc) in enumerate(directions)}

    def get_opposite_dir(dir_idx):
        return (dir_idx + 2) % 4

    def jump_point_search():
        open_set = [(0, start, None)]  # (priority, position, direction_index)
        came_from = {}
        g_score = {start: 0}
        f_score = {start: 0}
        dir_map = {}

        while open_set:
            _, current, current_dir = heapq.heappop(open_set)
            if current == goal:
                return reconstruct_path(came_from, start, current)

            for dr, dc in directions:
                next_pos = (current[0] + dr, current[1] + dc)
                if is_wall(next_pos) or next_pos in g_score:
                    continue
                tentative_g = g_score[current] + 1
                if not is_free(next_pos):
                    continue
                came_from[next_pos] = current
                g_score[next_pos] = tentative_g
                f_score[next_pos] = tentative_g
                dir_map[next_pos] = dir_to_index[(dr, dc)]
                heapq.heappush(open_set, (f_score[next_pos], next_pos, dir_to_index[(dr, dc)]))
                if is_jump_point(next_pos, dir_to_index[(dr, dc)]):
                    heapq.heappush(open_set, (f_score[next_pos], next_pos, dir_to_index[(dr, dc)]))
        return []

    def is_jump_point(pos, dir_idx):
        dr, dc = directions[dir_idx]
        r, c = pos

        next_pos = (r + dr, c + dc)
        if is_wall(next_pos):
            return False

        new_dir_idx = dir_to_index[(dr, dc)]

        if dir_idx == 0 or dir_idx == 1:  # Vertical
            up = (r - 1, c)
            down = (r + 1, c)
            l, r_cell = (r, c - 1), (r, c + 1)
            if is_free(up) and is_free(r_cell) and is_free(l):
                return True
            if is_free(down) and is_free(r_cell) and is_free(l):
                return True
        else:  # Horizontal
            left = (r, c - 1)
            right = (r, c + 1)
            up, down = (r - 1, c), (r + 1, c)
            if is_free(left) and is_free(up) and is_free(down):
                return True
            if is_free(right) and is_free(up) and is_free(down):
                return True

        if is_free((r + dr, c + dc)):
            if is_jump_point((r + dr, c + dc), new_dir_idx):
                return True
        return False

    def reconstruct_path(came_from, start, current):
        path = []
        while current != start:
            path.append(current)
            current = came_from[current]
        path.reverse()
        path.insert(0, start)
        return path

    if not is_free(start) or not is_free(goal):
        return []
