import heapq

def solve(grid, start, goal):
    def is_wall(pos):
        r, c = pos
        return not (0 <= r < len(grid) and 0 <= c < len(grid[r])) or grid[r][c] == '#'

    if start == goal:
        return [start] if not is_wall(start) else []

    if is_wall(start) or is_wall(goal):
        return []

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def heuristic(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def a_star(start_pos, goal_pos):
        visited = set()
        queue = [(0, start_pos, [])]
        while queue:
            (cost, (r, c), path) = heapq.heappop(queue)
            current = (r, c)
            if current in visited:
                continue
            path = path + [current]
            if current == goal_pos:
                return path
            visited.add(current)
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                next_pos = (nr, nc)
                if not is_wall(next_pos) and next_pos not in visited:
                    new_cost = len(path) + 1 + heuristic(next_pos, goal_pos)
                    heapq.heappush(queue, (new_cost, next_pos, path))
        return None

    path_from_start = a_star(start, goal)
    path_from_goal = a_star(goal, start)

    if path_from_start is not None:
        return path_from_start
    if path_from_goal is not None:
        return path_from_goal
    return []
