def solve(grid, start, goal):
    if start == goal:
        return [start]

    if not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0])) or \
       not (0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0])):
        return []

    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    directions = [(-1,0), (1,0), (0,-1), (0,1)]

    def heuristic(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def a_star_search(start, target, dir):
        rows, cols = len(grid), len(grid[0])
        came_from = {}
        open_set = [(0, start)]
        g_score = {start: 0}
        f_score = {start: heuristic(start, target)}
        visited = set()

        while open_set:
            _, current = heapq.heappop(open_set)
            if current in visited:
                continue
            if current == target:
                path = []
                while current in came_from:
                    path.append(current)
                    current = came_from[current]
                path.reverse()
                if dir == "goal_to_start":
                    return path
                else:
                    return [p for p in path if p != start] + [start] if path and path[-1] == start else path

            visited.add(current)
            for dr, dc in directions:
                nr, nc = current[0] + dr, current[1] + dc
                neighbor = (nr, nc)
                if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                    tentative_g = g_score[current] + 1
                    if tentative_g < g_score.get(neighbor, float('inf')):
                        came_from[neighbor] = current
                        g_score[neighbor] = tentative_g
                        f_score[neighbor] = tentative_g + heuristic(neighbor, target)
                        heapq.heappush(open_set, (f_score[neighbor], neighbor))
        return []

    path1 = a_star_search(start, goal, "start_to_goal")
    path2 = a_star_search(goal, start, "goal_to_start")

    if path1 and path2:
        first_half = [p for p in path1 if p in path2] or [path2[0]]
        full_path = [start]
        curr = start
        while curr != goal:
            for n in [(curr[0]+d[0], curr[1]+d[1]) for d in directions]:
