import heapq

def solve(grid, start, goal):
    if start == goal:
        return [start]
    if not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0])) or \
       not (0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0])):
        return []
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def heuristic(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def a_star(frontier, came_from, cost, goal, reverse):
        while frontier:
            current_cost, current = heapq.heappop(frontier)
            if current == goal:
                path = []
                while current is not None:
                    path.append(current)
                    current = came_from[current]
                return path[::-1] if not reverse else path
            for dx, dy in directions:
                nx, ny = current[0] + dx, current[1] + dy
                if 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] == '.':
                    neighbor = (nx, ny)
                    if neighbor not in cost or cost[current] + 1 < cost[neighbor]:
                        cost[neighbor] = cost[current] + 1
                        priority = cost[neighbor] + heuristic(neighbor, goal)
                        heapq.heappush(frontier, (priority, neighbor))
                        came_from[neighbor] = current
        return None

    # Forward search from start
    came_from_start = {}
    cost_start = {start: 0}
    frontier_start = [(0, start)]
    path_start = a_star(frontier_start, came_from_start, cost_start, goal, False)

    if path_start is not None:
        return path_start

    # Backward search from goal
    came_from_goal = {}
    cost_goal = {goal: 0}
    frontier_goal = [(0, goal)]
    path_goal = a_star(frontier_goal, came_from_goal, cost_goal, start, True)

    if path_goal is not None:
        return path_goal

    # Bidirectional search
    while frontier_start and frontier_goal:
        # Forward step
        _, current_start = heapq.heappop(frontier_start)
        for dx, dy in directions:
            nx, ny = current_start[0] + dx, current_start[1] + dy
            if 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] == '.':
                neighbor_start = (nx, ny)
                if neighbor_start not in cost_start or cost_start[current_start] + 1 < cost_start[neighbor_start]:
                    cost_start[neighbor_start] = cost_start[current_start] + 1
                    priority = cost_start[neighbor_start] + heuristic(neighbor_start, goal)
                    heapq.heappush(frontier_start, (priority, neighbor_start))
                    came_from_start[neighbor_start] = current_start
                    if neighbor_start in cost_goal:
                        path1 = []
                        path2 = []
                        c = neighbor_start
                        while c is not None:
                            path1.append(c)
                            c = came_from_start[c]
                        c = neighbor_start
                        while c is not None:
                            path2.append(c)
                            c = came_from_goal[c]
                        return path1[::-1] + path2[1:]

        # Backward step
        _, current_goal = heapq.heappop(frontier_goal)
        for dx, dy in directions:
            nx, ny = current_goal[0] + dx, current_goal[1] + dy
