        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                yield (nr, nc)

    def heuristic(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def a_star(start, goal, reverse=False):
        open_set = [(heuristic(start, goal), 0, start, [])]
        visited = set()
        while open_set:
            h, cost, current, path = heappop(open_set)
            if current in visited:
                continue
            visited.add(current)
