    def is_wall(pos):
        r, c = pos
        return not (0 <= r < len(grid) and 0 <= c < len(grid[0])) or grid[r][c] == '#'

    def get_neighbors(pos):
        r, c = pos
        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        return [(r + dr, c + dc) for dr, dc in directions if not is_wall((r + dr, c + dc))]

