import heapq

def solve(grid, start, goal):
    def is_wall(pos):
        r, c = pos
        return not (0 <= r < len(grid) and 0 <= c < len(grid[0])) or grid[r][c] == '#'

    if is_wall(start) or is_wall(goal):
        return []
    if start == goal:
        return [start]

    def heuristic(pos):
        pr, pc = pos
        gr, gc = target
        return abs(pr - gr) + abs(pc - gc)

    def a_star_search(start, target, grid):
        rows, cols = len(grid), len(grid[0])
        visited = set()
        queue = [(0, start, [start])]
        while queue:
            cost, current, path = heapq.heappop(queue)
            if current == target:
                return path
            if current in visited:
                continue
            visited.add(current)
            r, c = current
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                next_pos = (nr, nc)
                if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.' and next_pos not in visited:
                    new_path = path + [next_pos]
                    priority = len(new_path) + heuristic(next_pos)
                    heapq.heappush(queue, (priority, next_pos, new_path))
        return None

    path_from_start = a_star_search(start, goal, grid)
    path_from_goal = a_star_search(goal, start, grid)

    if path_from_start and path_from_goal:
        for idx, pos in enumerate(path_from_start):
            if pos in path_from_goal:
                return path_from_start[:idx+1] + path_from_goal[:path_from_goal.index(pos):-1]
